document.addEventListener("DOMContentLoaded", () => {
  initNavbar();
  initScrollReveal();
  initMobileMenu();
  initDropdowns();
  initLightbox();
  initInteractiveCards(".acco-card");
  initInteractiveCards(".idea-card");
  initToggleAmenities();
});
function initNavbar() {
  const navbar = document.querySelector(".navbar");
  if (!navbar) return;
  if (navbar.classList.contains("scrolled")) return;
  const onScroll = () => {
    navbar.classList.toggle("scrolled", window.scrollY > 60);
  };
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();
}
function initScrollReveal() {
  const els = document.querySelectorAll(".reveal");
  if (!els.length) return;
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting) {
          e.target.classList.add("revealed");
          observer.unobserve(e.target);
        }
      });
    },
    { threshold: 0.12, rootMargin: "0px 0px -40px 0px" }
  );
  els.forEach((el) => observer.observe(el));
}
function initMobileMenu() {
  const hamburger = document.querySelector(".hamburger");
  const navLinks = document.querySelector(".nav-links");
  if (!hamburger || !navLinks) return;
  function closeMobileMenu() {
    hamburger.classList.remove("active");
    navLinks.classList.remove("open");
    document.body.style.overflow = "";
  }
  hamburger.addEventListener("click", () => {
    const isOpen = navLinks.classList.contains("open");
    if (isOpen) {
      closeMobileMenu();
    } else {
      hamburger.classList.add("active");
      navLinks.classList.add("open");
      document.body.style.overflow = "hidden";
    }
  });
  navLinks.querySelectorAll("a:not(.dropdown-toggle)").forEach((a) => {
    a.addEventListener("click", closeMobileMenu);
  });
  document.addEventListener("click", (e) => {
    if (navLinks.classList.contains("open")) {
      if (!navLinks.contains(e.target) && !hamburger.contains(e.target)) {
        closeMobileMenu();
      }
    }
  });
}
function initDropdowns() {
  document.querySelectorAll(".dropdown-toggle").forEach((toggle) => {
    toggle.addEventListener("click", (e) => {
      if (window.innerWidth <= 1024) {
        e.preventDefault();
        toggle.closest("li").classList.toggle("dropdown-open");
      }
    });
  });
}
function initLightbox() {
  const lightbox = document.getElementById("lightbox");
  if (!lightbox) return;
  const lbImg = lightbox.querySelector("img");
  const lbClose = lightbox.querySelector(".lightbox-close");
  document.querySelectorAll(".gallery-item img").forEach((img) => {
    img.addEventListener("click", () => {
      lbImg.src = img.src;
      lbImg.alt = img.alt;
      if (typeof lbImg.decode === "function") {
        lbImg.decode().then(() => {
          lightbox.classList.add("active");
          document.body.style.overflow = "hidden";
        }).catch(() => {
          lightbox.classList.add("active");
          document.body.style.overflow = "hidden";
        });
      } else {
        lightbox.classList.add("active");
        document.body.style.overflow = "hidden";
      }
    });
  });
  const closeLb = () => {
    lightbox.classList.remove("active");
    document.body.style.overflow = "";
  };
  if (lbClose) lbClose.addEventListener("click", closeLb);
  lightbox.addEventListener("click", (e) => {
    if (e.target === lightbox) closeLb();
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeLb();
  });
}
let _toastTimer = null;
function showToast(message, type = "success") {
  let toast = document.querySelector(".toast");
  if (!toast) {
    toast = document.createElement("div");
    toast.className = "toast";
    document.body.appendChild(toast);
  }
  if (_toastTimer) {
    clearTimeout(_toastTimer);
  }
  toast.textContent = message;
  toast.className = `toast ${type}`;
  requestAnimationFrame(() => toast.classList.add("show"));
  _toastTimer = setTimeout(() => {
    toast.classList.remove("show");
    _toastTimer = null;
  }, 4e3);
}
function initInteractiveCards(selector) {
  const cards = document.querySelectorAll(selector);
  if (!cards.length) return;
  cards.forEach((card) => {
    card.addEventListener("click", (e) => {
      if (window.innerWidth > 1024) return;
      if (!card.classList.contains("is-active")) {
        if (card.tagName.toLowerCase() === "a") {
          e.preventDefault();
        }
        cards.forEach((c) => c.classList.remove("is-active"));
        card.classList.add("is-active");
      } else if (card.tagName.toLowerCase() !== "a") {
        card.classList.remove("is-active");
      }
    });
  });
  document.addEventListener("click", (e) => {
    if (!e.target.closest(selector)) {
      cards.forEach((c) => c.classList.remove("is-active"));
    }
  });
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((e) => {
      if (!e.isIntersecting) {
        e.target.classList.remove("is-active");
      }
    });
  }, { threshold: 0 });
  cards.forEach((card) => observer.observe(card));
}
function initToggleAmenities() {
  document.querySelectorAll(".btn-more-amenities").forEach((btn) => {
    const panelId = btn.getAttribute("data-panel");
    const panel = panelId ? document.getElementById(panelId) : null;
    if (!panel) return;
    btn.addEventListener("click", () => {
      const isOpen = panel.style.display !== "none";
      panel.style.display = isOpen ? "none" : "block";
      btn.classList.toggle("open", !isOpen);
      const label = btn.querySelector(".toggle-label");
      if (label) {
        label.textContent = isOpen ? "More..." : "Less";
      }
    });
  });
}
